package main

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"sync"

	"github.com/jepsen-io/maelstrom/demo/go"
)

// Message types we handle
type AddReq struct {
	Type      string `json:"type"`
	MessageID int    `json:"msg_id"`
	Delta     int64  `json:"delta"`
}

type AddOK struct {
	Type       string `json:"type"`
	InReplyTo  int    `json:"in_reply_to"`
	Value      int64  `json:"value,omitempty"` // Include value for clarity
}

type ReadReq struct {
	Type      string `json:"type"`
	MessageID int    `json:"msg_id"`
}

type ReadOK struct {
	Type       string `json:"type"`
	InReplyTo  int    `json:"in_reply_to"`
	Value      int64  `json:"value"`
}

func main() {
	node := maelstrom.NewNode("g-counter")
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// SeqKV for atomic counter operations
	seqkv := maelstrom.NewSeqKV(node)

	var mu sync.Mutex
	latestValue int64 = 0

	node.Handle(maelstrom.InitType, func(ctx context.Context, msg json.RawMessage, nodeID string, otherNodeIDs []string) maelstrom.Result {
		var init struct {
			Type       string   `json:"type"`
			NodeID     string    `json:"node_id"`
			OtherNodeIDs []string `json:"other_node_ids"`
		}
		if err := json.Unmarshal(msg, &init); err != nil {
			log.Printf("Error unmarshaling init: %v", err)
			return maelstrom.Result{}
		}

		node.Metadata.NodeID = init.NodeID
		log.Printf("Node %s initialized with other nodes: %v", node.Metadata.NodeID, init.OtherNodeIDs)
		log.Printf("Counter starts at 0")
		return maelstrom.Result{}
	})

	node.Handle(maelstrom.AddType, func(ctx context.Context, msg json.RawMessage) (m.MsgID, json.RawMessage, error) {
		var req AddReq
		if err := json.Unmarshal(msg, &req); err != nil {
			return 0, nil, fmt.Errorf("parse add: %v", err)
		}

		delta := int64(0)
		if req.Delta != 0 {
			delta = req.Delta
		}

		// Use CompareAndSwap atomically: only succeed if current value equals expected
		current, success, err := seqkv.ReadInt(ctx, "counter", "counter")
		if err != nil {
			log.Printf("seq-kv ReadInt error: %v", err)
			return 0, nil, err
		}

		var newValue int64 = current
		if success && delta > 0 {
			newValue = current + delta
		}

		valueToStore := int64(0)
		resultJSON, err := json.Marshal(&ReadOK{
			Type:       "add_ok",
			InReplyTo:  req.MessageID,
			Value:      newValue,
		})
		if err != nil {
			log.Printf("Error marshaling add_ok: %v", err)
			return 0, nil, err
		}

		// Atomically update the counter
		resultJSON2, err := seqkv.Write(ctx, "counter", fmt.Sprintf("%d", newValue), func() bool {
			log.Printf("[%s] CAS: expected %d, got %d, delta %d", node.Metadata.NodeID, current, int(current), delta)
			return success && (newValue == current+delta)
		})

		if err != nil {
			log.Printf("seq-kv Write error: %v", err)
		} else if resultJSON2 != nil {
			fmt.Println(string(resultJSON2))
		}

		mu.Lock()
		latestValue = newValue
		mu.Unlock()

		return 0, resultJSON2, nil
	})

	node.Handle(maelstrom.ReadType, func(ctx context.Context, msg json.RawMessage) (m.MsgID, json.RawMessage, error) {
		var req ReadReq
		if err := json.Unmarshal(msg, &req); err != nil {
			return 0, nil, fmt.Errorf("parse read: %v", err)
		}

		value, err := seqkv.ReadInt(ctx, "counter", "counter")
		if err != nil {
			log.Printf("seq-kv ReadInt error: %v", err)
			return 0, nil, err
		}

		resultJSON, err := json.Marshal(&ReadOK{
			Type:   "read_ok",
			Value:  value,
			InReplyTo: req.MessageID,
		})
		if err != nil {
			log.Printf("Error marshaling read_ok: %v", err)
			return 0, nil, err
		}

		fmt.Println(string(resultJSON))
		return 0, resultJSON, nil
	})

	node.Handle(maelstrom.InitType2, func(ctx context.Context, msg json.RawMessage, nodeID string, otherNodeIDs []string) maelstrom.Result {
		var init struct {
			Type             string   `json:"type"`
			NodeID           string    `json:"node_id"`
			OtherNodeIDs     []string `json:"other_node_ids"`
			Skip              int     `json:"skip,omitempty"`
		}
		if err := json.Unmarshal(msg, &init); err != nil {
			log.Printf("Error unmarshaling init2: %v", err)
			return maelstrom.Result{}
		}

		if init.Skip > 0 {
			return maelstrom.Result{Skip: true}
		}

		node.Metadata.NodeID = init.NodeID
		log.Printf("Node %s initialized with other nodes: %v", node.Metadata.NodeID, init.OtherNodeIDs)
		log.Printf("Counter starts at 0")
		return maelstrom.Result{}
	})

	if err := node.Run(ctx); err != nil {
		log.Fatalf("Error running node: %v", err)
	}
}

