import (
	"context"
	"fmt"

	"github.com/jepsen-io/maelstrom/demo/go"
)

func main() {
	ctx := context.Background()
	node := go.NewNode()

	// Use seq-kv for atomic counter operations
	seqkv := go.NewSeqKV(node)

	// Handle init message - set up initial state
	node.Init("init", func(msg go.Message) error {
		// Initialize local state to 0 before we start reading from seq-kv
		// The first read of the key will return 0 from seq-kv if it doesn't exist
		return nil
	})

	// Handle add requests
	node.Handle(go.AddType, func(msg go.Message) error {
		var req struct {
			Type   string `json:"type"`
			MsID   int    `json:"msg_id"`
			Delta  int64  `json:"delta"`
		}
		if err := msg.Body.Unmarshal(&req); err != nil {
			return fmt.Errorf("parse add: %v", err)
		}

		// Use CompareAndSwap to atomically increment the counter
		// This ensures no double-counting or lost increments
		err := seqkv.CompareAndSwap(ctx, "counter", 0, req.Delta, true)

		// Now read the current value
		current, err2 := seqkv.ReadInt(ctx, "counter")
		if err != nil && err2 == nil {
			return err
		}

		// Reply with the new value
		reply := go.NewReply(msg, struct {
			Type       string `json:"type"`
			InReplyTo  int    `json:"in_reply_to"`
			Value      int64  `json:"value"`
		}{
			Type:       "add_ok",
			InReplyTo:  req.MsID,
			Value:      int64(current),
		})

		return reply.Marshal()
	})

	// Handle read requests
	node.Handle(go.ReadType, func(msg go.Message) error {
		var req struct {
			Type   string `json:"type"`
			MsID   int    `json:"msg_id"`
		}
		if err := msg.Body.Unmarshal(&req); err != nil {
			return fmt.Errorf("parse read: %v", err)
		}

		current, err := seqkv.ReadInt(ctx, "counter")
		if err != nil {
			return fmt.Errorf("read counter: %v", err)
		}

		reply := go.NewReply(msg, struct {
			Type       string `json:"type"`
			InReplyTo  int    `json:"in_reply_to"`
			Value      int64  `json:"value"`
		}{
			Type:   "read_ok",
			Value:  int64(current),
			InReplyTo: req.MsID,
		})

		return reply.Marshal()
	})

	return node.Run(ctx)
}

